import{_ as o,o as t,c as a,a5 as r}from"./chunks/framework.DvE3tBec.js";const u=JSON.parse('{"title":"Introduction","description":"","frontmatter":{},"headers":[],"relativePath":"documentation/1.0/index.md","filePath":"documentation/1.0/README.md","lastUpdated":1791387718000}'),n={name:"documentation/1.0/index.md"};function i(s,e,l,p,c,d){return t(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="introduction" tabindex="-1">Introduction <a class="header-anchor" href="#introduction" aria-label="Permalink to &quot;Introduction&quot;">​</a></h1><p>First of all, a good idea is to get familiar with the terminology in openEO by reading the <a href="./glossary.html">glossary</a>. There&#39;s also an in-depth <a href="./datacubes.html">introduction to datacubes</a> and processing them with openEO.</p><p>Currently, there are three official client libraries, a web-based interface for openEO and a QGIS plugin.</p><p>If you are <strong>unfamiliar</strong> with programming, you could start using the <a href="https://editor.openeo.org" target="_blank" rel="noreferrer">web-based editor for openEO</a>. It supports visual modelling of your algorithms and a simplified JavaScript based access to the openEO workflows and providers. openEO can also be used in QGIS through a <a href="./qgis/">QGIS plugin</a>.</p><p>If you are <strong>familiar</strong> with programming, you could choose a client library for three programming languages:</p><ul><li><a href="./javascript/">JavaScript</a> (client-side and server-side)</li><li><a href="./python/">Python</a></li><li><a href="./r/">R</a></li></ul><p>Follow the links above to find usage instructions for each of the client libraries.</p><p>For details about available processes, see the <strong><a href="./processes.html">list of openEO processes</a></strong>. The <strong><a href="./cookbook/">openEO Cookbook</a></strong> describes common use-cases with code examples in all three languages.</p><p>The more advanced topic to run your own code on back-ends, is explained in the introduction to <a href="./udfs.html">openEO UDFs (user-defined functions)</a>.</p><div class="tip custom-block"><p class="custom-block-title">Note</p><p>This is the documentation for the <strong>openEO API version 1.0</strong>. If you are looking for other versions of openEO, please use the version switch at the top right of this page.</p></div><h2 id="contribute" tabindex="-1">Contribute <a class="header-anchor" href="#contribute" aria-label="Permalink to &quot;Contribute&quot;">​</a></h2><p>Didn&#39;t find your programming language? You can also access the <a href="./developers/api/reference.html">openEO API</a> implementations directly or start <a href="./developers/clients/getting-started.html">implementing your own client library</a>.</p><p>If you are missing any functionality in the API feel free to <a href="https://github.com/Open-EO/openeo-api/issues" target="_blank" rel="noreferrer">open an issue</a> or actively start proposing API changes as Pull Requests.</p><p>Feel free to contact us for further assistance.</p>',14)])])}const f=o(n,[["render",i]]);export{u as __pageData,f as default};
